def transform(grid):
    h, w = len(grid), len(grid[0])
    # Split at the full row or column separator.
    sep_row = next((r for r, row in enumerate(grid)
                    if len(set(row)) == 1 and row[0] != 0), None)
    if sep_row is not None:
        top, bottom = grid[:sep_row], grid[sep_row + 1:]
        out = []
        for r in range(min(len(top), len(bottom))):
            a, b = top[r], bottom[r]
            bg_a = max(set(a), key=a.count)
            bg_b = max(set(b), key=b.count)
            out.append([2 if a[c] != bg_a and b[c] != bg_b else 0
                        for c in range(min(len(a), len(b)))])
        return out

    sep_col = next((c for c in range(w)
                    if len({grid[r][c] for r in range(h)}) == 1), None)
    left = [row[:sep_col] for row in grid]
    right = [row[sep_col + 1:] for row in grid]
    out = []
    for a, b in zip(left, right):
        bg_a = max(set(a), key=a.count)
        bg_b = max(set(b), key=b.count)
        out.append([2 if x != bg_a and y != bg_b else 0
                    for x, y in zip(a, b)])
    return out
